// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 off) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0); // plain EOA so the payout transfer succeeds
        off = bound(off, 0, 200); // settle shortly after the target block

        // In Foundry, after rolling, blockhash(n) is deterministically
        // keccak256(abi.encode(n)) for recently passed blocks.
        uint256 lockBlock = block.number;
        uint256 target = lockBlock + 1;
        bytes32 h = keccak256(abi.encode(target)); // the answer the reference must store verbatim

        vm.deal(actor, 2 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);

        vm.roll(lockBlock + 2 + off);
        vm.prank(actor);
        c.settle();

        // Reference: guess stored raw matches blockhash -> pays out everything (balance 0).
        // Mutant: stores keccak256(abi.encodePacked(h)) which never equals the blockhash,
        // so settle never pays and the balance stays at 2 ether.
        assertTrue(address(c).balance == 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 h) public {
        // Admissible domain: a distinct caller with a hash that is NOT a keccak fixed point
        // (fixed points are excluded because the reference legitimately stores h == keccak(h) there).
        vm.assume(actor != address(0));
        vm.assume(keccak256(abi.encodePacked(h)) != h);

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);

        (uint storedBlock, bytes32 storedGuess) = c.guesses(actor);
        assertTrue(storedBlock != 0 && storedGuess == h);
    }
}

