pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 startBlock) public {
        vm.assume(actor != address(0) && actor != address(c));
        // bound start block so target block stays within blockhash's recent-window validity
        startBlock = bound(startBlock, 1, type(uint256).max / 2);

        // choose the target block deterministically: the block right after lockInGuess
        vm.roll(startBlock);
        uint256 target = block.number + 1;
        bytes32 winningGuess = blockhash(target);

        // lock in the exact blockhash of the target block
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(winningGuess);

        // advance past the target block and settle
        vm.roll(target + 1);
        vm.prank(actor);
        c.settle();

        // general rule: guessing the correct blockhash always wins the full prize,
        // so c must be drained of its entire balance for EVERY admissible input.
        assertTrue(address(c).balance == 0, "correct guess must win the 2 ether prize");
    }
}

