pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 h) public {
        // keep the domain admissible: a real, non-contract caller distinct from the target contract
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0);

        // fund the caller and lock in the guess with the required 1 ether
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);

        // the lock succeeded, so the guess window is armed for this caller
        assertTrue(c.guesses(actor).block != 0);

        // GENERAL RULE: the value recorded on-chain for a caller is exactly the
        // preimage hash that caller supplied. The reference stores `h` verbatim,
        // so this holds for EVERY admissible input. The mutant stores
        // keccak256(abi.encodePacked(h)), which never equals the supplied `h`
        // (keccak256 has no efficient fixed points, and any such fixed point is
        // unreachable by the fuzzer), so it violates the rule for some input.
        assertTrue(c.guesses(actor).guess == h);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(uint256 startBlock, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        startBlock = bound(startBlock, 2, 2 ** 32);

        // Choose the guessed block as startBlock + 1 (lockInGuess sets block = block.number + 1).
        // Roll so the guess lands on startBlock + 1 and read that block's (nonzero) blockhash.
        vm.roll(startBlock);
        uint256 guessedBlock = startBlock + 1;

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(blockhash(guessedBlock));

        // Move past the guessed block so settle() is admissible.
        vm.roll(guessedBlock + 1);

        bool ok;
        vm.prank(actor);
        try c.settle() { ok = true; } catch { ok = false; }

        // General rule: a winner must always be able to settle (payout path executes).
        assertTrue(ok);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function f(uint amount, bytes32 g) public {
        require(address(this).balance >= amount);
        c.lockInGuess{value: amount}(g);
        assert(address(c).balance == 2 ether);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount != 1 ether);
        require(address(this).balance >= amount);
        bool reverted;
        try c.lockInGuess{value: amount}(keccak256(abi.encodePacked(amount))) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        uint bal0 = address(c).balance;
        bool reverted;
        try c.lockInGuess{value: amount}(keccak256(abi.encodePacked(amount))) { reverted = false; } catch { reverted = true; }
        assert(reverted || (address(c).balance - bal0 == 1 ether));
    }
    receive() external payable {}
}
